import { readFileSync, writeFileSync } from 'node:fs';
import { z } from 'zod';
import type { DB } from '../db/index.js';

/**
 * AI snapshot: the permit summaries already generated by GreenRoute, plus the real call log that
 * produced them. Deploys restore it instead of re-calling Gemini on every build (free-tier quotas
 * are small). Summaries are restored only for permits whose content hash still matches, so an
 * edited permit is re-summarized rather than shown stale.
 */
const SnapshotSchema = z.object({
  exportedAt: z.string(),
  summaries: z.array(
    z.object({ permit_id: z.string(), content_hash: z.string(), summary_json: z.string(), generator: z.string(), created_at: z.string() }),
  ),
  cache: z.array(
    z.object({
      cache_key: z.string(),
      task: z.string(),
      model: z.string(),
      result_json: z.string(),
      input_tokens: z.number(),
      output_tokens: z.number(),
      created_at: z.string(),
    }),
  ),
  calls: z.array(z.record(z.string(), z.union([z.string(), z.number(), z.null()]))),
});

export function exportSnapshot(db: DB, path: string): { summaries: number; cache: number; calls: number } {
  const snapshot = {
    exportedAt: new Date().toISOString(),
    summaries: db.prepare('SELECT permit_id, content_hash, summary_json, generator, created_at FROM permit_summaries ORDER BY permit_id').all(),
    cache: db.prepare('SELECT * FROM ai_cache ORDER BY cache_key').all(),
    calls: db.prepare('SELECT * FROM ai_calls ORDER BY id').all(),
  };
  writeFileSync(path, JSON.stringify(SnapshotSchema.parse(snapshot), null, 1));
  return { summaries: snapshot.summaries.length, cache: snapshot.cache.length, calls: snapshot.calls.length };
}

export function restoreSnapshot(db: DB, path: string): { summaries: number; cache: number; calls: number } {
  const snapshot = SnapshotSchema.parse(JSON.parse(readFileSync(path, 'utf8')));
  const counts = { summaries: 0, cache: 0, calls: 0 };
  const currentHash = db.prepare('SELECT content_hash FROM permits WHERE id = ?');
  const insertSummary = db.prepare(
    `INSERT OR REPLACE INTO permit_summaries (permit_id, content_hash, summary_json, generator, created_at) VALUES (?, ?, ?, ?, ?)`,
  );
  const insertCache = db.prepare(
    `INSERT OR IGNORE INTO ai_cache (cache_key, task, model, result_json, input_tokens, output_tokens, created_at)
     VALUES (@cache_key, @task, @model, @result_json, @input_tokens, @output_tokens, @created_at)`,
  );
  const insertCall = db.prepare(
    `INSERT INTO ai_calls (created_at, request_id, task, stage, route_reason, model, input_tokens, output_tokens, cost_usd,
       baseline_cost_usd, energy_wh_est, baseline_energy_wh_est, latency_ms, cache_hit, fallback, success, error_code)
     VALUES (@created_at, @request_id, @task, @stage, @route_reason, @model, @input_tokens, @output_tokens, @cost_usd,
       @baseline_cost_usd, @energy_wh_est, @baseline_energy_wh_est, @latency_ms, @cache_hit, @fallback, @success, @error_code)`,
  );
  db.transaction(() => {
    for (const s of snapshot.summaries) {
      const row = currentHash.get(s.permit_id) as { content_hash: string } | undefined;
      if (row?.content_hash !== s.content_hash) continue;
      insertSummary.run(s.permit_id, s.content_hash, s.summary_json, s.generator, s.created_at);
      counts.summaries += 1;
    }
    for (const c of snapshot.cache) counts.cache += insertCache.run(c).changes;
    // The generation history is restored once (an empty log), so the dashboard shows how the summaries were really made.
    const existingCalls = (db.prepare('SELECT COUNT(*) AS n FROM ai_calls').get() as { n: number }).n;
    if (existingCalls === 0) {
      for (const call of snapshot.calls) {
        const { id: _id, ...rest } = call;
        insertCall.run(rest);
        counts.calls += 1;
      }
    }
  })();
  return counts;
}
